+
+    fn handle_visual_key(&mut self, key: UiKey) -> Vec<UiAction> {
+        match key {
+            UiKey::Esc => {
+                self.clear_visual_selection();
+            }
+            UiKey::Char('y') => {
+                self.copy_visual_selection(false);
+            }
+            UiKey::Char('Y') => {
+                self.copy_visual_selection(true);
+            }
+            UiKey::Char('h') | UiKey::Left => {
+                self.move_visual_cursor(0, -1);
+            }
+            UiKey::Char('j') | UiKey::Down => {
+                self.move_visual_cursor(1, 0);
+            }
+            UiKey::Char('k') | UiKey::Up => {
+                self.move_visual_cursor(-1, 0);
+            }
+            UiKey::Char('l') | UiKey::Right => {
+                self.move_visual_cursor(0, 1);
+            }
+            _ => {}
+        }
+        Vec::new()
+    }
+
+    fn start_visual_selection(&mut self, kind: VisualSelectionKind) {
+        self.mode = UiMode::Command;
+        let position = self.visual_start_position(self.focus);
+        self.visual_selection = Some(VisualSelection {
+            focus: self.focus,
+            kind,
+            anchor: position,
+            cursor: position,
+        });
+    }
+
+    fn clear_visual_selection(&mut self) {
+        self.visual_selection = None;
+    }
+
+    fn visual_start_position(&self, focus: PaneFocus) -> VisualPosition {
+        match focus {
+            PaneFocus::Left => {
+                let lines = self.left_content_lines();
+                VisualPosition {
+                    row: self.control_selected.min(lines.len().saturating_sub(1)),
+                    column: 0,
+                }
+            }
+            PaneFocus::Right => VisualPosition { row: 0, column: 0 },
+        }
+    }
+
+    fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        let lines = self.visual_lines(selection.focus);
+        let max_row = lines.len().saturating_sub(1);
+        let next_row = move_index(selection.cursor.row, row_delta, max_row);
+        let max_column = lines
+            .get(next_row)
+            .map(|line| line.chars().count().saturating_sub(1))
+            .unwrap_or(0);
+        let next_column = move_index(selection.cursor.column, column_delta, max_column);
+        if let Some(selection) = self.visual_selection.as_mut() {
+            selection.cursor = VisualPosition {
+                row: next_row,
+                column: next_column,
+            };
+        }
+    }
+
+    fn copy_visual_selection(&mut self, force_linewise: bool) {
+        let Some(mut selection) = self.visual_selection else {
+            return;
+        };
+        if force_linewise {
+            selection.kind = VisualSelectionKind::Line;
+        }
+        let text = selected_text(&self.visual_lines(selection.focus), selection);
+        self.store_copied_text(text);
+        self.clear_visual_selection();
+    }
+
+    fn copy_current_line(&mut self) {
+        let lines = self.visual_lines(self.focus);
+        let row = self
+            .visual_start_position(self.focus)
+            .row
+            .min(lines.len().saturating_sub(1));
+        let text = lines.get(row).cloned().unwrap_or_default();
+        self.store_copied_text(text);
+    }
+
+    fn store_copied_text(&mut self, text: String) {
+        let copied_chars = text.chars().count();
+        self.copied_text = Some(text.clone());
+        self.pending_clipboard_copy.replace(Some(text));
+        self.show_status_notice(
+            format!("copied {copied_chars} chars"),
+            Duration::from_secs(STATUS_NOTICE_SECONDS),
+        );
+    }
+
+    fn visual_lines(&self, focus: PaneFocus) -> Vec<String> {
+        match focus {
+            PaneFocus::Left => self.left_content_lines(),
+            PaneFocus::Right => self.cached_right_lines.borrow().clone(),
+        }
+    }
+
+    fn left_content_lines(&self) -> Vec<String> {
+        let inner_width = usize::from(self.layout().left_width.saturating_sub(2).max(1));
+        let mut lines = vec![truncate_to_width(
+            if self.control_selected == 0 {
+                "> work-leaf  command"
+            } else {
+                "  work-leaf  command"
+            },
+            inner_width,
+        )];
+        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
+            let agent = &self.agents[*agent_index];
+            let selected = self.control_selected == visible_position + 1;
+            lines.push(compact_agent_row(agent, selected, inner_width));
+            if !agent.modified_files.is_empty() {
+                lines.push(truncate_to_width(
+                    &format!(
+                        "    files: {}",
+                        agent
+                            .modified_files
+                            .iter()
+                            .map(|path| path.display().to_string())
+                            .collect::<Vec<_>>()
+                            .join(", ")
+                    ),
+                    inner_width,
+                ));
+            }
+            for (label, agents) in [
+                ("conflicts", &agent.conflicting_agents),
+                ("depends-on", &agent.depends_on),
+                ("depended-on-by", &agent.depended_on_by),
+            ] {
+                if !agents.is_empty() {
+                    lines.push(truncate_to_width(
+                        &format!(
+                            "    {label}: {}",
+                            agents
+                                .iter()
+                                .map(AgentId::as_str)
+                                .collect::<Vec<_>>()
+                                .join(", ")
+                        ),
+                        inner_width,
+                    ));
+                }
+            }
+        }
+        lines
+    }
+
+    fn apply_visual_selection(&self, buffer: &mut Buffer, right_content: &str) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        let Some((origin_x, origin_y, width, height, lines)) =
+            self.visual_pane_context(selection.focus, right_content)
+        else {
+            return;
+        };
+        let width = usize::from(width);
+        let height = usize::from(height);
+        for (line_index, start, end) in selected_line_ranges(&lines, selection, width) {
+            if line_index >= height {
+                continue;
+            }
+            let start = start.min(width);
+            let end = end.min(width);
+            for column in start..end {
+                let x = origin_x.saturating_add(column.min(usize::from(u16::MAX)) as u16);
+                let y = origin_y.saturating_add(line_index.min(usize::from(u16::MAX)) as u16);
+                buffer.get_mut(x, y).modifier.insert(Modifier::REVERSED);
+            }
+        }
+    }
+
+    fn visual_cursor_position(
+        &self,
+        selection: VisualSelection,
+        right_content: &str,
+    ) -> (u16, u16) {
+        let Some((origin_x, origin_y, width, height, lines)) =
+            self.visual_pane_context(selection.focus, right_content)
+        else {
+            return (1, 1);
+        };
+        let row = selection
+            .cursor
+            .row
+            .min(lines.len().saturating_sub(1))
+            .min(usize::from(height.saturating_sub(1)));
+        let line_width = lines
+            .get(row)
+            .map(|line| line.chars().count())
+            .unwrap_or(0);
+        let column = selection
+            .cursor
+            .column
+            .min(line_width.saturating_sub(1))
+            .min(usize::from(width.saturating_sub(1)));
+        (
+            origin_y.saturating_add(row.min(usize::from(u16::MAX)) as u16),
+            origin_x.saturating_add(column.min(usize::from(u16::MAX)) as u16),
+        )
+    }
+
+    fn visual_pane_context(
+        &self,
+        focus: PaneFocus,
+        right_content: &str,
+    ) -> Option<(u16, u16, u16, u16, Vec<String>)> {
+        let layout = self.layout();
+        let body_height = self.height.saturating_sub(1);
+        let inner_height = body_height.saturating_sub(2);
+        match focus {
+            PaneFocus::Left if self.left_visible && layout.left_width > 0 => Some((
+                1,
+                1,
+                layout.left_width.saturating_sub(2),
+                inner_height,
+                self.left_content_lines(),
+            )),
+            PaneFocus::Left => None,
+            PaneFocus::Right => {
+                let right_x = if self.left_visible { layout.left_width } else { 0 };
+                Some((
+                    right_x.saturating_add(1),
+                    1,
+                    layout.right_width.saturating_sub(2),
+                    inner_height,
+                    content_lines(right_content),
+                ))
+            }
+        }
+    }

