+#[test]
+fn scripted_harness_visual_character_copy_uses_right_pane_focus() {
+    let mut harness = UiHarness::new(80, 24);
+    let _ = harness.render_frame();
+
+    harness.handle_bytes(&[23, b'l']);
+    harness.handle_bytes(b"vl");
+
+    let selected_frame = harness.render_frame();
+    assert!(selected_frame.contains("\u{1b}[7mUI\u{1b}[0m"));
+
+    harness.handle_byte(b'y');
+
+    assert_eq!(harness.ui().copied_text(), Some("UI"));
+    assert_eq!(harness.ui().mode(), UiMode::Command);
+    assert!(!harness.ui().has_visual_selection());
+}
+
